  p_apRough = texelFetch(lookSettings, ivec2(4, 1), 0).r;
  p_apCoat = texelFetch(lookSettings, ivec2(5, 1), 0).r;
  p_apCoatRough = texelFetch(lookSettings, ivec2(6, 1), 0).r;
  p_apPeel = texelFetch(lookSettings, ivec2(7, 1), 0).r;
  p_apPeelDepth = texelFetch(lookSettings, ivec2(8, 1), 0).r;
  p_apDust = texelFetch(lookSettings, ivec2(9, 1), 0).r;
